const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<span class="symbol" aria-hidden="true">${name}</span>`;
const internalLink=(href,label)=>`<a class="text-link" href="${href}" ${href.startsWith('#/')?'':`data-scroll-to="${href.slice(1)}"`}>${label}${icon('arrow_forward')}</a>`;
const table=(rows)=>`<div class="table-scroll"><table class="spec-table"><thead><tr><th>Elemento</th><th>Contrato del paquete</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div>`;
const list=items=>`<ul class="doc-list">${items.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`;
const section=(id,title,body)=>`<section class="doc-section" id="${id}"><h2>${title}</h2>${body}</section>`;
const screenReaderCases=new Set(['buttons','tabs','lists','text-fields','checkbox','menus']);
const largeTextCases=new Set(['buttons','tabs','lists','text-fields','menus','date-pickers','time-pickers','search']);
function nativePicture(c){return `<figure class="native-picture"><a data-native-link="${c.id}" href="./native/${c.id}.png" target="_blank" rel="noopener noreferrer" aria-label="Ampliar captura nativa de ${esc(c.title)}"><img data-native-image="${c.id}" src="./native/${c.id}.png" alt="${esc(c.title)}: captura de la galería del componente" width="220" height="478"></a><figcaption>Componente original<br>Captura del 2 de noviembre de 2026</figcaption></figure>`;}
function platformNote(){return `<div class="scope-note">${icon('smartphone')}<p>Implementación documentada: <strong>React Native con módulos Expo</strong>. El soporte web del paquete se conserva y queda <a href="#/support">pendiente de verificación</a>.</p></div>`;}
function nativePanel(c){return `<div class="native-proof"><div class="native-proof-header"><span>${icon('smartphone')}Vista del paquete nativo</span><button class="icon-button" data-action="theme" aria-label="Cambiar tema de la documentación">${icon('dark_mode')}</button></div><div class="native-proof-body">${nativePicture(c)}<div><h3>Funcionamiento</h3><ol class="behavior-list">${c.guide.behavior.map(([title,text])=>`<li><strong>${esc(title)}</strong><p>${esc(text)}</p></li>`).join('')}</ol><p class="responsive-note">La captura es estática. Los ejemplos de esta ficha importan y ejecutan el componente nativo; aquí no se simulan sus gestos con HTML.</p>${internalLink('#example','Ver implementación en React Native')}</div></div></div>`;}
function integration(c){return section('implementation','Integración en la pantalla',list(c.guide.integration)+`<p>${internalLink('#/start','Preparar el proveedor y las dependencias')}</p>`);}
function examples(c,{codeCard}){return section('example','Implementación y ejemplos',`<p>Este módulo utiliza <code>${esc(c.primaryExport)}</code> de <code>mobile-design</code>. El estado pertenece al consumidor. Los ejemplos se verifican contra la API local, no contra una reconstrucción HTML.</p>${codeCard(c.example,c.primaryExport+'.tsx','./examples/'+c.id+'.tsx')}${c.recipes.map(recipe=>`<article class="recipe"><h3>${esc(recipe.title)}</h3><p>${esc(recipe.description)}</p>${codeCard(recipe.code,recipe.id+'.tsx','./examples/'+recipe.id+'.tsx')}</article>`).join('')}`);}
function variants(c){return section('variants','Variantes y configuraciones',c.variants.length?`<div class="variant-grid">${c.variants.map(v=>`<span class="variant-tag">${esc(v)}</span>`).join('')}</div>${c.configurations?.length?`<h3 style="margin-top:28px">Configuraciones y estados</h3><div class="tag-row">${c.configurations.map(v=>`<span class="pill">${esc(v)}</span>`).join('')}</div>`:''}`:`<p>Esta familia no define variantes independientes. Sus opciones se expresan mediante propiedades y estados.</p>${c.configurations?.length?`<div class="tag-row">${c.configurations.map(v=>`<span class="pill">${esc(v)}</span>`).join('')}</div>`:''}`);}
function apiRow(prop){return `<tr data-prop="${esc(prop.name)}"><td><code>${esc(prop.name)}</code>${prop.required?'<span class="required">REQUERIDA</span>':''}${prop.default!==undefined?`<span class="default-value">Inicial: <code>${esc(prop.default)}</code></span>`:''}</td><td class="api-type">${prop.type.length>110?`<details><summary><code>${esc(prop.type.slice(0,100))}…</code></summary><code>${esc(prop.type)}</code></details>`:`<code>${esc(prop.type)}</code>`}${prop.description?`<p class="prop-description">${esc(prop.description)}</p>`:''}</td></tr>`;}
const apiTable=properties=>`<div class="table-scroll"><table class="api-table"><thead><tr><th>Propiedad</th><th>Tipo y descripción</th></tr></thead><tbody>${properties.map(apiRow).join('')}</tbody></table></div>`;

export const componentDocs={
 overview(c,context){return `<section class="doc-section" id="in-action">${platformNote()}${nativePanel(c)}</section>${section('when','Cuándo usarlo',`<p>${esc(c.guidance)}</p>`)}${integration(c)}${variants(c)}${examples(c,context)}`;},
 specs(c){const config=c.api.filter(p=>/^(size|sizeClass|width|height|maximum|minimum|orientation|alignment|variant|shape|thickness|density|edgePadding)/.test(p.name));const defaults=c.api.filter(p=>p.default!==undefined);return `${section('anatomy','Anatomía y composición',`<p>${esc(c.description)}</p><div class="tag-row">${c.exports.map(name=>`<span class="pill">${icon('code')}${esc(name)}</span>`).join('')}</div>`+list(c.guide.integration))}${section('dimensions','Dimensiones y configuración',`<p>Medidas y opciones de la implementación local. React Native utiliza unidades lógicas; contenido, texto del sistema y tamaño de ventana pueden modificar el espacio necesario.</p>${c.dimensions.length?table(c.dimensions):`<p>Esta familia resuelve su geometría según el contenido y su contenedor. Las propiedades disponibles y sus tipos se detallan aquí y en la sección API.</p>`}${config.length?table(config.map(p=>[p.name,p.type.replace(/ \| undefined$/,'')])):''}`)}${defaults.length?section('defaults','Valores iniciales',`<p>Valores extraídos de los parámetros de la implementación. Las opciones no listadas deben consultarse en el tipo correspondiente; no se deduce un valor por su apariencia.</p>${table(defaults.map(p=>[p.name,p.default]))}`):''}${section('tokens','Tema, estados y movimiento',table([['Color','Roles semánticos del proveedor compartido.'],['Tipografía','Roboto y variantes de texto del tema.'],['Iconos','Material Symbols Rounded mediante la configuración de iconos.'],['Movimiento','Perfil del proveedor y preferencia de movimiento reducido.']])+`<p>${internalLink('#/styles','Ver configuración de estilos')}</p>`+list(c.guide.cautions))}`;},
 api(c,context){return `${section('import','Importación',context.codeCard(`import { ${c.primaryExport} } from 'mobile-design';`,c.primaryExport+'.tsx')+`<p>Exportaciones de la familia: ${c.exports.map(name=>`<code>${esc(name)}</code>`).join(', ')}.</p>`)}<section class="doc-section" id="properties"><div class="section-top"><h2>Propiedades</h2><label class="page-filter-search">${icon('search')}<input type="search" id="api-filter" placeholder="Buscar propiedad" aria-label="Buscar propiedad"></label></div><p>Tipos extraídos de <code>${esc(c.primaryExport)}</code>. Las propiedades heredadas visibles forman parte de esta selección de API. Los valores iniciales sólo se muestran cuando se han extraído de la función original.</p>${apiTable(c.api)}<p id="api-count" class="responsive-note">${c.api.length} propiedades · sincronizado el ${esc(context.data.generated)}</p></section>${c.relatedTypes.length?section('contracts','Contratos y tipos relacionados',`<p>Formas de los datos que utiliza esta familia. Son contratos del paquete, no atributos de controles HTML.</p>${c.relatedTypes.map(type=>`<details class="contract-type"><summary><code>${esc(type.name)}</code><span>${type.properties.length} propiedades</span>${icon('expand_more')}</summary>${type.properties.length?apiTable(type.properties):'<p>Tipo compuesto; consulta los tipos de las propiedades del componente y sus ejemplos de uso.</p>'}</details>`).join('')}`):''}${examples(c,context)}`;},
 accessibility(c){return `${section('semantics','Semántica e interacción',`<p>${esc(c.accessibility)}</p>`+list(c.guide.accessibility))}${section('focus','Integración accesible',`<p>El componente y la pantalla comparten la responsabilidad de conservar nombre, estado, foco y resultado de la acción.</p>`+list(c.guide.integration)+`<h3>Acciones y estados que deben coincidir</h3>${table(c.guide.behavior)}<h3>Revisión en la pantalla</h3>${list(['Comprueba el orden de lectura y la disponibilidad de cada acción.','Amplía el texto del sistema y verifica etiquetas, controles y contenido desplazable.','Activa movimiento reducido y conserva el significado de los estados.','Al cerrar una superficie modal, comprueba que pueda continuarse la tarea anterior.'])}`)}${section('coverage','Evidencia y alcance',table([['Galería del componente','Capturas claras/oscuras y estado con movimiento reducido.'],['Lector de pantalla',screenReaderCases.has(c.id)?'Recorrido representativo observado en esta familia.':'Sin recorrido específico acreditado en la revisión.'],['Texto ampliado',largeTextCases.has(c.id)?'Caso representativo ejecutado con texto del sistema ampliado.':'Sin caso específico de texto ampliado acreditado en el cierre.'],['Web','Código conservado. Validación de componentes en navegador pendiente.']])+`<p>${internalLink('#/verification','Consultar los casos y límites de la revisión')}</p>`)}`;}
};
